## Manifest 完整接口定义

以下 JSON 与插件包内实际 `manifest.json` 逐字段一致，覆盖插件身份、权限、配置、鉴权、参数、校验、创建、Agent、查询、取消、结果下载、响应和 Agent 响应映射。`documentation` 字段的值就是当前完整文档；为避免文档在自身内部无限递归，JSON 中仅用等义占位文本表示正文。

```json
{
  "apiVersion": "yingce.plugin/v2",
  "id": "autodl-comfyui",
  "name": "AutoDL ComfyUI 视频与音频",
  "version": "2.2.0",
  "author": "影策社区",
  "description": "通过 AutoDL.Art ComfyUI 工作流 API 接入异步视频与音频生成，新增 H3 Z0901 文生视频、Z0902 六图生视频与 Z0903 六图三音频生视频工作流。",
  "documentation": "<当前插件的完整 documentation，由 README.md 与 docs/interface.md 拼接而成；为避免 JSON 递归，此处不重复展开正文。>",
  "permissions": [
    "generation.run",
    "media.read"
  ],
  "configuration": {
    "fields": [
      {
        "name": "apiKey",
        "type": "secret",
        "label": "AutoDL Token",
        "required": true,
        "description": "填写 AutoDL 大模型令牌管理中创建的 ComfyUI 分组 Token。"
      }
    ]
  },
  "contributes": {
    "providers": [
      {
        "id": "autodl-comfyui",
        "label": "AutoDL ComfyUI 视频",
        "capabilities": [
          "video"
        ],
        "scopes": [
          "admin.system-channel",
          "user.custom-channel",
          "canvas",
          "creation"
        ],
        "baseUrl": "https://autodl.art",
        "requiresPublicMediaUrls": true,
        "auth": {
          "type": "header",
          "field": "apiKey",
          "header": "Authorization"
        },
        "parameters": [
          {
            "name": "prompt",
            "type": "string",
            "required": true,
            "mapping": "prompt",
            "description": "视频生成提示词。"
          },
          {
            "name": "duration",
            "type": "integer",
            "mapping": "duration",
            "description": "视频时长（秒）。"
          },
          {
            "name": "resolution",
            "type": "string",
            "mapping": "resolution",
            "description": "输出分辨率档位，如 480p竖、768p竖、1080p竖、480p横、768p横、1080p横、480p(1:1)、768p(1:1) 等。"
          },
          {
            "name": "images",
            "type": "media[]",
            "mapping": "first_frame/last_frame 或 ref_image_N",
            "description": "先按 first_frame、last_frame、reference_image 等 role 分流，再按 order 为工作流生成 ref_image_N；不再用数组 0/1 猜测角色。"
          },
          {
            "name": "audios",
            "type": "media[]",
            "mapping": "ref_audio_N",
            "description": "按 order 生成 ref_audio_N，最多取工作流支持的前三项。"
          }
        ],
        "create": {
          "method": "POST",
          "path": "/api/v1/comfyui/comfyui_workflow/{{model}}",
          "contentType": "application/json",
          "body": {
            "$merge": [
              {
                "prompt": {
                  "$if": {
                    "condition": {
                      "$ne": [
                        {
                          "$ref": "request.model"
                        },
                        "minimax_h3_image_audio_to_video"
                      ]
                    },
                    "then": {
                      "$ref": "request.prompt"
                    }
                  }
                },
                "duration": {
                  "$if": {
                    "condition": {
                      "$ne": [
                        {
                          "$ref": "request.model"
                        },
                        "minimax_h3_image_audio_to_video"
                      ]
                    },
                    "then": {
                      "$ref": "request.duration"
                    }
                  }
                },
                "audio_duration": {
                  "$if": {
                    "condition": {
                      "$eq": [
                        {
                          "$ref": "request.model"
                        },
                        "minimax_h3_image_audio_to_video"
                      ]
                    },
                    "then": {
                      "$ref": "request.duration"
                    }
                  }
                },
                "resolution": {
                  "$omitEmpty": {
                    "$lower": {
                      "$ref": "request.resolution"
                    }
                  }
                }
              },
              {
                "$if": {
                  "condition": {
                    "$in": [
                      {
                        "$ref": "request.model"
                      },
                      [
                        "minimax_h3_b99_003_12s",
                        "minimax_h3_image_audio_to_video_v2_15s",
                        "minimax_h3_lightx2v_v5_15s",
                        "minimax_h3_image_audio_to_video_v2",
                        "minimax_h3_lightx2v_v5",
                        "minimax_h3_zm_u24",
                        "minimax_h3_zm_u08",
                        "minimax_h3_z0902",
                        "minimax_h3_z0903"
                      ]
                    ]
                  },
                  "then": {
                    "$indexObject": {
                      "from": {
                        "$filter": {
                          "from": {
                            "$sortByOrder": {
                              "$ref": "request.images"
                            }
                          },
                          "as": "media",
                          "where": {
                            "$in": [
                              {
                                "$ref": "media.role"
                              },
                              [
                                "reference_image",
                                "subject_reference",
                                "style_reference",
                                "edit_source",
                                ""
                              ]
                            ]
                          }
                        }
                      },
                      "as": "media",
                      "prefix": "ref_image_",
                      "max": 9,
                      "value": {
                        "$ref": "media.value"
                      }
                    }
                  },
                  "else": {}
                }
              },
              {
                "$if": {
                  "condition": {
                    "$in": [
                      {
                        "$ref": "request.model"
                      },
                      [
                        "minimax_h3_b99_002",
                        "minimax_h3_lightx2v"
                      ]
                    ]
                  },
                  "then": {
                    "first_frame": {
                      "$omitEmpty": {
                        "$coalesce": [
                          {
                            "$first": {
                              "$map": {
                                "from": {
                                  "$filter": {
                                    "from": {
                                      "$sortByOrder": {
                                        "$ref": "request.images"
                                      }
                                    },
                                    "as": "media",
                                    "where": {
                                      "$eq": [
                                        {
                                          "$ref": "media.role"
                                        },
                                        "first_frame"
                                      ]
                                    }
                                  }
                                },
                                "as": "media",
                                "in": {
                                  "$ref": "media.value"
                                }
                              }
                            }
                          },
                          {
                            "$at": [
                              {
                                "$map": {
                                  "from": {
                                    "$sortByOrder": {
                                      "$ref": "request.images"
                                    }
                                  },
                                  "as": "media",
                                  "in": {
                                    "$ref": "media.value"
                                  }
                                }
                              },
                              0
                            ]
                          }
                        ]
                      }
                    },
                    "last_frame": {
                      "$omitEmpty": {
                        "$coalesce": [
                          {
                            "$first": {
                              "$map": {
                                "from": {
                                  "$filter": {
                                    "from": {
                                      "$sortByOrder": {
                                        "$ref": "request.images"
                                      }
                                    },
                                    "as": "media",
                                    "where": {
                                      "$eq": [
                                        {
                                          "$ref": "media.role"
                                        },
                                        "last_frame"
                                      ]
                                    }
                                  }
                                },
                                "as": "media",
                                "in": {
                                  "$ref": "media.value"
                                }
                              }
                            }
                          },
                          {
                            "$at": [
                              {
                                "$map": {
                                  "from": {
                                    "$sortByOrder": {
                                      "$ref": "request.images"
                                    }
                                  },
                                  "as": "media",
                                  "in": {
                                    "$ref": "media.value"
                                  }
                                }
                              },
                              1
                            ]
                          }
                        ]
                      }
                    }
                  },
                  "else": {}
                }
              },
              {
                "$if": {
                  "condition": {
                    "$eq": [
                      {
                        "$ref": "request.model"
                      },
                      "minimax_h3_image_audio_to_video"
                    ]
                  },
                  "then": {
                    "ref_image_0": {
                      "$omitEmpty": {
                        "$first": {
                          "$map": {
                            "from": {
                              "$sortByOrder": {
                                "$ref": "request.images"
                              }
                            },
                            "as": "media",
                            "in": {
                              "$ref": "media.value"
                            }
                          }
                        }
                      }
                    }
                  },
                  "else": {}
                }
              },
              {
                "$if": {
                  "condition": {
                    "$in": [
                      {
                        "$ref": "request.model"
                      },
                      [
                        "minimax_h3_image_audio_to_video",
                        "minimax_h3_image_audio_to_video_v2",
                        "minimax_h3_image_audio_to_video_v2_15s",
                        "minimax_h3_z0903"
                      ]
                    ]
