                  "then": {
                    "$indexObject": {
                      "from": {
                        "$sortByOrder": {
                          "$ref": "request.audios"
                        }
                      },
                      "as": "media",
                      "prefix": "ref_audio_",
                      "max": 3,
                      "value": {
                        "$ref": "media.value"
                      }
                    }
                  },
                  "else": {}
                }
              }
            ]
          }
