            "type": "string",
            "required": false,
            "mapping": "aspect_ratio",
            "description": "画幅比例。"
          },
          {
            "name": "resolution",
            "type": "string",
            "required": false,
            "mapping": "resolution/size",
            "description": "输出分辨率档位。"
          },
          {
            "name": "generateAudio",
